// === Tab: mySketch ===
let particles = []
let lapse = 0;    // mouse timer

function setup() {
	createCanvas(1112, 834);
	background(0);
	colorMode(HSB)
	for(var o=0;o<height;o+=10){
	  for(var i=0;i<width;i+=10)
			{
			particles.push({
			  x:i,
			  y:o,
			  clr: color(random(360),80,80)
			})
		}
	}
}

function draw() {
	noStroke()

	for(var i=0;i<particles.length;i++){
		let p = particles[i]
		fill(p.clr)
		ellipse(p.x,p.y,5)
		p.x+= (noise(p.x/200,p.y/200,100)-0.5)*3
		p.y+= (noise(p.x/200,p.y/200,1000)-0.5)*3
	}
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 200){
    save('pix.jpg');
    lapse = millis();
  }
}

